type BuiltInScreenLayoutField = { key: string; label: string; visible: boolean; position: number; fixed?: boolean; section?: string | null }
function groupBuiltInScreenFields(fields: BuiltInScreenLayoutField[]) {
  if (!fields.some(field => field.section?.trim())) return []
  return fields.reduce<{ label: string; count: number }[]>((groups, field) => {
    const label = field.section?.trim() || 'Genel'
    const current = groups[groups.length - 1]
    if (current?.label === label) current.count++
    else groups.push({ label, count: 1 })
    return groups
  }, [])
}
