  async function save(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api('/api/access-control/rules',token,{method:'POST',body:JSON.stringify({subjectType,subjectRole:subjectType==='Role'?subjectRole:null,subjectUserId:subjectType==='User'?subjectUserId:null,permissionCode,effect,resourceType:null,attributeName:attributeName||null,attributeOperator:attributeName?operator:null,attributeValue:attributeName?attributeValue:null})});setNotice('İzin politikası kaydedildi.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
