    try { const result=await api<StockItemUnitConversion>(`/api/stock/items/${costTarget.stockItemId}/units`,token,{method:'POST',body:JSON.stringify({unitCode:unitCodeNew,factorToBase:Number(unitFactorNew)})});setUnitConversions(current=>[...current.filter(x=>x.id!==result.id),result]);setUnitCodeNew('');setNotice(`${result.unitCode} birimi ${result.factorToBase} ${costTarget.unitCode} olarak tanımlandı.`) }
