    try { await api<InventoryCostAdjustment>(`/api/purchasing/receipts/${landedReceiptId}/landed-costs`,token,{method:'POST',body:JSON.stringify({entryDate:revaluationDate,amountBase:Number(landedAmount),allocationMethod:landedMethod,description:landedDescription})});setLandedAmount('');setLandedDescription('');setNotice('Ek maliyet mal kabul satırlarına dağıtıldı.');setLandedAdjustments(await api<InventoryCostAdjustment[]>(`/api/purchasing/receipts/${landedReceiptId}/landed-costs`,token));if(costTarget)await openCostManager(costTarget);await loadBalances() }
