  useEffect(()=>{let cancelled=false;api<{fields:BuiltInScreenLayoutField[]}>('/api/screen-views/sales-invoices/active',token).then(view=>{if(!cancelled&&view.fields?.length)setInvoiceScreenFields(view.fields)}).catch(()=>{});return()=>{cancelled=true}},[token])
