  async function openOrderFieldHistory(field:PurchaseOrderFieldDefinition){setError('');try{setOrderFieldHistory(await api<PurchaseOrderFieldRevision[]>(`/api/purchasing/orders/custom-fields/${field.id}/history`,token));setOrderFieldHistoryDefinition(field)}catch(e){setError((e as Error).message)}}
  async function restoreOrderFieldRevision(revision:PurchaseOrderFieldRevision){if(!orderFieldHistoryDefinition||!window.confirm(`v${revision.version} alan tanımı yeni sürüm olarak geri yüklensin mi?`))return;setBusy(true);setError('');try{await api(`/api/purchasing/orders/custom-fields/${revision.definitionId}/restore`,token,{method:'POST',body:JSON.stringify({version:revision.version,confirmation:true})});setNotice(`v${revision.version} tanımı yeni sürüm olarak geri yüklendi.`);await load();await openOrderFieldHistory(orderFieldHistoryDefinition)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
