  async function openRequestFieldHistory(field:PurchaseRequestFieldDefinition){setError('');try{setRequestFieldMetadataHistory(await api<PurchaseRequestFieldMetadataRevision[]>(`/api/purchasing/requests/custom-fields/${field.id}/history`,token));setRequestFieldHistoryDefinition(field)}catch(e){setError((e as Error).message)}}
  async function restoreRequestFieldRevision(revision:PurchaseRequestFieldMetadataRevision){if(!window.confirm(`v${revision.version} alan tanımı yeni sürüm olarak geri yüklensin mi?`))return;setBusy(true);setError('');try{await api(`/api/purchasing/requests/custom-fields/${revision.definitionId}/restore`,token,{method:'POST',body:JSON.stringify({version:revision.version,confirmation:true})});setNotice(`v${revision.version} tanımı yeni sürüm olarak geri yüklendi.`);await load();if(requestFieldHistoryDefinition)await openRequestFieldHistory(requestFieldHistoryDefinition)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
