  async function restoreRequestValueRevision(revision:PurchaseRequestFieldValueRevision){if(!requestDetail||!requestValueHistoryField||!window.confirm(`'${requestValueHistoryField.label}' alanı için bu kayıt öncesindeki değer geri yüklensin mi?`))return;setBusy(true);setError('');try{await api(`/api/purchasing/requests/${requestDetail.id}/custom-fields/${revision.definitionId}/history/${revision.id}/restore`,token,{method:'POST',body:JSON.stringify({confirmation:true})});setNotice('Önceki değer geri yüklendi ve yeni geçmiş kaydı eklendi.');await openRequest(requestDetail.id);await openRequestValueHistory(requestValueHistoryField)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function saveRequestCustomFields(e:React.FormEvent){e.preventDefault();if(!requestDetail)return;setBusy(true);setError('');try{const fields=await api<PurchaseRequestFieldValue[]>(`/api/purchasing/requests/${requestDetail.id}/custom-fields`,token,{method:'PUT',body:JSON.stringify({values:requestFieldValues})});setRequestDetail({...requestDetail,customFields:fields});setNotice('Satın alma talebi özel alanları kaydedildi.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function createRequest(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{const saved=await api<PurchaseRequestSummary>('/api/purchasing/requests/',token,{method:'POST',body:JSON.stringify({code:requestCode,requestDate,neededByDate:neededByDate||null,description:requestDescription,lines:requestLines.map(x=>({stockItemId:x.stockItemId,quantity:Number(x.quantity),unitCode:x.unitCode||stockItems.find(item=>item.id===x.stockItemId)?.unitCode})),customFields:requestFieldValues})});setRequestEditor(false);setRequestCode('');setNeededByDate('');setRequestDescription('');setRequestLines([{stockItemId:'',quantity:'1',unitCode:''}]);setNotice(`${saved.code} satın alma talebi onaya gönderildi.`);await load(1)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function decideRequest(request:PurchaseRequestSummary|PurchaseRequestDetail,approved:boolean){const note=approved?window.prompt('Onay notu (isteğe bağlı):')?.trim()||null:window.prompt('Ret gerekçesi:')?.trim();if(!approved&&!note)return;if(!window.confirm(approved?'Bu talep onaylansın mı?':'Bu talep reddedilsin mi?'))return;setBusy(true);setError('');setNotice('');try{await api(`/api/purchasing/requests/${request.id}/decision`,token,{method:'POST',body:JSON.stringify({approved,note})});setNotice(`${request.code} talebi ${approved?'onaylandı':'reddedildi'}.`);setRequestDetail(null);await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  function beginOrderConversion(request:PurchaseRequestDetail,quote?:PurchaseSupplierQuote){setConversionCode('');setConversionSupplierId(quote?.supplierId||'');setConversionDate(today);setConversionTargetWarehouseId('');setConversionNotes(quote?`Tedarikçi teklifi ${quote.code}`:'');setSelectedQuoteForOrder(quote?.id||null);setConversionPrices(Object.fromEntries(request.lines.map(line=>{const priced=quote?.lines.find(x=>x.requestLineNumber===line.lineNumber);return [line.lineNumber,{unitPrice:priced?.unitPrice.toString()||'0',discountPercent:priced?.discountPercent.toString()||'0',vatPercent:priced?.vatPercent.toString()||'20'}]})));setConversionFieldValues(Object.fromEntries(orderFieldDefinitions.map(field=>[field.code,request.customFields?.find(value=>value.code.toLowerCase()===field.code.toLowerCase())?.value||''])));setOrderConversion(true)}
  async function convertPurchaseRequest(e:React.FormEvent){e.preventDefault();if(!requestDetail)return;setBusy(true);setError('');setNotice('');try{const created=await api<PurchaseOrderSummary>(`/api/purchasing/requests/${requestDetail.id}/order`,token,{method:'POST',body:JSON.stringify({code:conversionCode,supplierId:conversionSupplierId,orderDate:conversionDate,expectedReceiptDate:requestDetail.neededByDate,targetWarehouseId:conversionTargetWarehouseId||null,notes:conversionNotes||null,supplierQuoteId:selectedQuoteForOrder,customFields:conversionFieldValues,lines:requestDetail.lines.map(line=>({lineNumber:line.lineNumber,unitPrice:Number(conversionPrices[line.lineNumber]?.unitPrice||0),discountPercent:Number(conversionPrices[line.lineNumber]?.discountPercent||0),vatPercent:Number(conversionPrices[line.lineNumber]?.vatPercent||0)}))})});setOrderConversion(false);setRequestDetail(null);setNotice(`${created.code} siparişi ${requestDetail.code} talebinden oluşturuldu.`);await load();await openOrder(created.id)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  function beginQuoteCapture(request:PurchaseRequestDetail){setQuoteCode('');setQuoteSupplierId('');setQuoteDate(today);setQuoteValidUntil('');setQuoteNotes('');setQuotePrices(Object.fromEntries(request.lines.map(line=>[line.lineNumber,{unitPrice:'0',discountPercent:'0',vatPercent:'20'}])));setSupplierQuoteFieldValues(Object.fromEntries(supplierQuoteFieldDefinitions.map(field=>[field.code,''])));setQuoteEditor(true)}
  async function createSupplierQuote(e:React.FormEvent){e.preventDefault();if(!requestDetail)return;setBusy(true);setError('');setNotice('');try{const quote=await api<PurchaseSupplierQuote>(`/api/purchasing/requests/${requestDetail.id}/supplier-quotes`,token,{method:'POST',body:JSON.stringify({code:quoteCode,supplierId:quoteSupplierId,quoteDate,validUntil:quoteValidUntil||null,notes:quoteNotes||null,customFields:supplierQuoteFieldValues,lines:requestDetail.lines.map(line=>({requestLineNumber:line.lineNumber,unitPrice:Number(quotePrices[line.lineNumber]?.unitPrice||0),discountPercent:Number(quotePrices[line.lineNumber]?.discountPercent||0),vatPercent:Number(quotePrices[line.lineNumber]?.vatPercent||0)}))})});setSupplierQuotes(current=>[...current,quote].sort((a,b)=>a.currencyCode.localeCompare(b.currencyCode)||a.grandTotal-b.grandTotal));setQuoteEditor(false);setNotice(`${quote.supplierName} için ${quote.code} teklifi kaydedildi.`)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function createSupplierQuoteCustomField(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await api('/api/purchasing/supplier-quotes/custom-fields',token,{method:'POST',body:JSON.stringify({code:supplierQuoteFieldCode,label:supplierQuoteFieldLabel,dataType:supplierQuoteFieldType,maxLength:Number(supplierQuoteFieldMaxLength),isRequired:supplierQuoteFieldRequired})});setSupplierQuoteFieldCode('');setSupplierQuoteFieldLabel('');setSupplierQuoteFieldType('Text');setSupplierQuoteFieldMaxLength('200');setSupplierQuoteFieldRequired(false);setNotice('Tedarikçi teklifi özel alanı oluşturuldu.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function editSupplierQuoteCustomField(field:PurchaseSupplierQuoteFieldDefinition){const label=window.prompt('Alan etiketi',field.label)?.trim();if(!label)return;const maxLength=field.dataType==='Text'?Number(window.prompt('En fazla karakter',String(field.maxLength))):0;if(field.dataType==='Text'&&(!Number.isInteger(maxLength)||maxLength<1||maxLength>500))return;const isRequired=window.confirm('Bu alan zorunlu olsun mu?');setBusy(true);setError('');try{await api(`/api/purchasing/supplier-quotes/custom-fields/${field.id}`,token,{method:'PUT',body:JSON.stringify({label,maxLength,isRequired})});setNotice('Tedarikçi teklifi alanı güncellendi.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function deactivateSupplierQuoteCustomField(field:PurchaseSupplierQuoteFieldDefinition){if(!window.confirm(`${field.label} alanı devre dışı bırakılsın mı? Eski teklifler korunur.`))return;setBusy(true);setError('');try{await api(`/api/purchasing/supplier-quotes/custom-fields/${field.id}`,token,{method:'DELETE'});setNotice('Tedarikçi teklifi alanı devre dışı bırakıldı.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
