      <div className="ledger-list"><table className="customer-table quote-detail-table"><thead><tr><th>Stok</th><th>Miktar</th><th>Birim fiyat</th><th>İskonto</th><th>KDV</th><th>Toplam</th></tr></thead><tbody>{invoice.lines.map(line=><tr key={line.id}><td><b>{line.stockCode}</b><small className="cell-subtitle">{line.stockName}</small></td><td>{line.quantity.toLocaleString('tr-TR',{maximumFractionDigits:4})} {line.unitCode}</td><td>{line.unitPrice.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:4})}</td><td>{line.discountAmount.toLocaleString('tr-TR',{minimumFractionDigits:2})} ({line.discountPercent}%)</td><td>{line.taxAmount.toLocaleString('tr-TR',{minimumFractionDigits:2})} ({line.vatPercent}%)</td><td>{line.lineTotal.toLocaleString('tr-TR',{minimumFractionDigits:2})}</td></tr>)}</tbody></table></div>
