      <div className="ledger-list"><table className="customer-table"><thead><tr><th>İade no</th><th>Tarih</th><th>Depo</th><th>Satır</th><th>Tutar</th><th>Durum</th><th></th></tr></thead><tbody>{invoice.returns.map(item=><tr key={item.id}><td><span className="customer-code">{item.code}</span></td><td>{item.returnDate.split('-').reverse().join('.')}</td><td>{item.warehouseName}</td><td>{item.lineCount}</td><td>{item.grandTotal.toLocaleString('tr-TR',{minimumFractionDigits:2})} {invoice.currencyCode}</td><td><span className={`quote-status ${item.status==='Posted'?'accepted':'rejected'}`}>{item.status==='Posted'?'İşlendi':'İptal'}</span></td><td>{item.status==='Posted'&&<button className="row-action danger-action" disabled={busy} onClick={()=>void voidReturn(item)}>İptal et</button>}</td></tr>)}{invoice.returns.length===0&&<tr><td colSpan={7} className="table-empty">Henüz alış iadesi yok.</td></tr>}</tbody></table></div>
      {returnEditor&&<form onSubmit={createReturn} className="collection-form"><div className="form-two"><label>İade tarihi<input type="date" value={returnDate} onChange={e=>setReturnDate(e.target.value)} required/></label><label>Çıkış deposu<select value={returnWarehouseId} onChange={e=>{setReturnWarehouseId(e.target.value);void loadReturnLocations(e.target.value)}} required><option value="">Depo seçin</option>{warehouses.filter(x=>x.isActive).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label></div><div className="ledger-list"><table className="customer-table"><thead><tr><th>Stok</th><th>Fatura miktarı</th><th>İade edilebilir</th><th>İade miktarı</th></tr></thead><tbody>{invoice.lines.map(line=>{const returned=invoice.returns.filter(r=>r.status==='Posted').flatMap(r=>r.lines).filter(r=>r.purchaseInvoiceLineId===line.id).reduce((sum,r)=>sum+r.quantity,0);const remaining=Math.max(0,line.quantity-returned);return <tr key={line.id}><td><b>{line.stockCode}</b><small className="cell-subtitle">{line.stockName}</small></td><td>{line.quantity.toLocaleString('tr-TR',{maximumFractionDigits:4})} {line.unitCode}</td><td>{remaining.toLocaleString('tr-TR',{maximumFractionDigits:4})}</td><td><select aria-label={`${line.stockCode} alış iade birimi`} value={enteredReturnUnits[line.id]||line.unitCode} onChange={e=>setEnteredReturnUnits(current=>({...current,[line.id]:e.target.value}))}><option value={line.unitCode}>{line.unitCode}</option>{(returnUnits[line.id]||[]).filter(u=>u.isActive&&u.unitCode!==line.unitCode).map(u=><option key={u.id} value={u.unitCode}>{u.unitCode}</option>)}</select><input aria-label={`${line.stockCode} alış iade miktarı`} type="number" min="0" step="0.0001" value={returnQuantities[line.id]||''} onChange={e=>setReturnQuantities(current=>({...current,[line.id]:e.target.value}))}/><select aria-label={`${line.stockCode} alış iade konumu`} value={returnLocationIds[line.id]||''} onChange={e=>setReturnLocationIds(current=>({...current,[line.id]:e.target.value}))}><option value="">Depo düzeyi</option>{returnLocations.map(location=><option key={location.id} value={location.id}>{location.code} · {location.name}</option>)}</select></td></tr>})}</tbody></table></div><div className="modal-foot"><span>İade, tedarikçi cari borcunu azaltır.</span><div><button type="button" className="secondary" onClick={()=>setReturnEditor(false)}>Vazgeç</button><button className="primary" disabled={busy||!returnWarehouseId||!invoice.lines.some(line=>Number(returnQuantities[line.id]||0)>0)}>{busy?'Kaydediliyor…':'İadeyi kaydet'}</button></div></div></form>}
