      {invoice.status==='Posted'&&invoice.outstandingAmount>0&&<form onSubmit={createPayment} className="collection-form"><div className="form-two"><label>Ödeme tarihi<input type="date" value={paymentDate} onChange={e=>setPaymentDate(e.target.value)} required/></label><label>Tutar ({invoice.currencyCode})<input type="number" min="0.01" max={invoice.outstandingAmount} step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} required/></label></div><div className="form-two"><label>Ödeme yöntemi<select value={method} onChange={e=>{setMethod(e.target.value as SupplierPayment['paymentMethod']);setFinancialAccountId('')}}><option value="Bank transfer">Havale / EFT</option><option value="Cash">Nakit</option><option value="Card">Kart</option><option value="Check">Çek</option></select></label><label>Referans <span className="optional-label">İsteğe bağlı</span><input value={reference} onChange={e=>setReference(e.target.value)} maxLength={100} placeholder="Dekont veya işlem numarası"/></label></div>{(method==='Cash'||method==='Bank transfer')&&<div className="form-two"><label>{method==='Cash'?'Kasa hesabı':'Banka hesabı'}<select value={financialAccountId} onChange={e=>setFinancialAccountId(e.target.value)} required><option value="">Hesap seçin</option>{eligibleAccounts.map(a=><option key={a.id} value={a.id}>{a.code} · {a.name} ({a.balance.toLocaleString('tr-TR',{minimumFractionDigits:2})} {a.currencyCode})</option>)}</select></label>{eligibleAccounts.length===0&&<span className="optional-label">Bu dövizde aktif hesap yok. Önce Finans ekranından hesap açın.</span>}</div>}<div className="modal-foot"><span>En fazla {invoice.outstandingAmount.toLocaleString('tr-TR',{minimumFractionDigits:2})} {invoice.currencyCode} ödenebilir.</span><button className="primary" disabled={busy||((method==='Cash'||method==='Bank transfer')&&!eligibleAccounts.length)}>{busy?'Kaydediliyor…':'Ödeme kaydet'}</button></div></form>}
